/**
 * Tests for null or empty. Does not check for length
 * @param value
 * @return
 */
private boolean includeValue(String value) {
    if (includeEmpty) {
        return true;
    }
    if (StringUtils.isBlank(value)) {
        return false;
    }
    return true;
}
